-- The Founder skill pack: one row per run. Only Jarvis's own short summary and step log are kept here; working files live in data/founder-work/.
CREATE TABLE founder_runs (id TEXT PRIMARY KEY, mode TEXT NOT NULL, project TEXT NOT NULL, request TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('running','done','stopped','failed')), steps INTEGER NOT NULL DEFAULT 0, cost_micro INTEGER NOT NULL DEFAULT 0, summary TEXT NOT NULL DEFAULT '', error TEXT, log TEXT NOT NULL DEFAULT '[]', files TEXT NOT NULL DEFAULT '[]', web INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
